begin;
select no_plan();
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000004',true);
select is(private.optimizer_exclusion(jsonb_populate_record(null::public.optimizer_profiles,'{"consent":"subscribed","suppression_reasons":[],"hard_bounce":false,"spam":false,"last_order_at":"2023-03-01T00:00:00Z"}'),'2024-03-01T00:00:00Z'),'protected_purchaser_12_months','twelve calendar months protects exact boundary across leap year');
select is(private.optimizer_exclusion(jsonb_populate_record(null::public.optimizer_profiles,'{"consent":"subscribed","suppression_reasons":[],"hard_bounce":false,"spam":false,"last_order_at":"2023-02-28T23:59:59Z"}'),'2024-03-01T00:00:00Z'),'eligible_nonengaged','older-than-twelve-month order alone does not permanently protect');
select public.install_optimizer_fixture('00000000-0000-4000-8000-000000000102');select public.install_optimizer_fixture('00000000-0000-4000-8000-000000000102');
select is((select count(*) from public.optimizer_profiles),8::bigint,'fixture installation is persisted and idempotent');
select set_config('test.p2',(select id::text from public.optimizer_profiles where external_id='original-fixture-2'),true);
select set_config('test.s',public.preview_optimizer('00000000-0000-4000-8000-000000000102',now())::text,true);
select is((select count(*) from public.optimizer_candidates where sweep_id=current_setting('test.s')::uuid and eligible),2::bigint,'only two consented nonengaged candidates qualify');
select is((select reason from public.optimizer_candidates c join public.optimizer_profiles p on p.id=c.profile_id where c.sweep_id=current_setting('test.s')::uuid and p.external_id='original-fixture-3'),'protected_purchaser_12_months','purchaser at 200 days remains protected despite 180-day candidate rule');
select ok(not exists(select 1 from public.optimizer_candidates c join public.optimizer_profiles p on p.id=c.profile_id where c.eligible and (p.hard_bounce or p.spam or p.consent<>'subscribed')),'hard bounce/spam/consent never enter winback');
select public.change_fixture_profile_evidence('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,1,'subscribed',false,false,false);
select throws_ok($$select public.approve_optimizer('00000000-0000-4000-8000-000000000102',current_setting('test.s')::uuid,1)$$,'40001',null,'evidence change invalidates exact preview');
select set_config('test.s',public.preview_optimizer('00000000-0000-4000-8000-000000000102',now())::text,true);
select public.approve_optimizer('00000000-0000-4000-8000-000000000102',current_setting('test.s')::uuid,1);
select set_config('test.s2',public.preview_optimizer('00000000-0000-4000-8000-000000000102',now())::text,true);
select throws_ok($$select public.approve_optimizer('00000000-0000-4000-8000-000000000102',current_setting('test.s2')::uuid,1)$$,'23514',null,'concurrent sweep cannot duplicate in-flight winback');
create function pg_temp.run_optimizer() returns void language plpgsql as $$
declare j public.job_runs;x jsonb;
begin
 loop select * into j from public.claim_job('00000000-0000-4000-8000-000000000102');exit when j.id is null;
 if j.kind not in ('optimizer.winback','optimizer.suppress') then raise exception 'Unexpected test job';end if;
 x:=public.fixture_optimizer_payload(j.id,j.lease_token);perform public.finish_optimizer_job(j.id,j.lease_token,x);
 end loop;
end $$;
select pg_temp.run_optimizer();
select is((select count(*) from public.optimizer_events where kind='winback_1'),2::bigint,'only eligible consented profiles receive first local message audit');
select is(public.advance_optimizer_clock('00000000-0000-4000-8000-000000000102',current_setting('test.s')::uuid,now()+interval '4 days'),0,'second winback does not mature at four days');
select public.advance_optimizer_clock('00000000-0000-4000-8000-000000000102',current_setting('test.s')::uuid,now()+interval '5 days');select pg_temp.run_optimizer();
select is((select count(*) from public.optimizer_events where kind='recovered'),1::bigint,'synthetic responder recovers without suppression');
select is((select count(*) from public.optimizer_events where kind='winback_2'),1::bigint,'remaining eligible profile receives second original local message audit');
select is((select count(*) from public.optimizer_profiles where 'optimizer'=any(suppression_reasons)),0::bigint,'winback does not prematurely suppress');
select public.advance_optimizer_clock('00000000-0000-4000-8000-000000000102',current_setting('test.s')::uuid,now()+interval '10 days');select pg_temp.run_optimizer();
select is((select state from public.optimizer_sweeps where id=current_setting('test.s')::uuid),'completed','ten-day sweep reaches persisted completion');
select is((select count(*) from public.optimizer_profiles where 'optimizer'=any(suppression_reasons)),1::bigint,'only eligible nonresponder receives optimizer reason');
select ok(not exists(select 1 from public.optimizer_profiles where external_id in ('original-fixture-1','original-fixture-3','original-fixture-4','original-fixture-5','original-fixture-6','original-fixture-8') and 'optimizer'=any(suppression_reasons)),'purchasers/responders/consent/bounce/spam remain protected');
select public.advance_optimizer_clock('00000000-0000-4000-8000-000000000102',current_setting('test.s')::uuid,now()+interval '10 days');select pg_temp.run_optimizer();
select is((select count(*) from public.optimizer_events where kind='suppressed'),1::bigint,'replay never duplicates suppression audit');
select ok((select pricing_snapshot->>'measuredSavings'='false' and pricing_snapshot->>'source'='fictional_fixture_rate' from public.optimizer_sweeps where id=current_setting('test.s')::uuid),'pricing is a dated fictional estimate, not measured savings');
select public.change_fixture_profile_evidence('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,3,'unsubscribed',false,false,false);
select throws_ok($$select public.reverse_fixture_suppression('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,4)$$,'23514',null,'blanket reversal cannot lift unsubscribed consent');
select public.change_fixture_profile_evidence('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,4,'subscribed',true,false,false);
select throws_ok($$select public.reverse_fixture_suppression('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,5)$$,'23514',null,'hard bounce and protected reasons cannot be lifted');
select public.change_fixture_profile_evidence('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,5,'subscribed',false,false,false);
select public.reverse_fixture_suppression('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,6);
select is((select cardinality(suppression_reasons) from public.optimizer_profiles where id=current_setting('test.p2')::uuid),0,'owner reversal removes only eligible optimizer reason');
select is((select count(*) from public.optimizer_events where kind='reversed'),1::bigint,'reversal retains actor/reason/version audit');
select is((select count(*) from public.optimizer_profiles),8::bigint,'suppression and reversal preserve profile history');
select set_config('test.s3',public.preview_optimizer('00000000-0000-4000-8000-000000000102',now())::text,true);
select public.approve_optimizer('00000000-0000-4000-8000-000000000102',current_setting('test.s3')::uuid,1);select pg_temp.run_optimizer();
select public.change_fixture_profile_evidence('00000000-0000-4000-8000-000000000102',current_setting('test.p2')::uuid,7,'subscribed',false,false,true);
select public.advance_optimizer_clock('00000000-0000-4000-8000-000000000102',current_setting('test.s3')::uuid,now()+interval '11 days');select pg_temp.run_optimizer();
select public.advance_optimizer_clock('00000000-0000-4000-8000-000000000102',current_setting('test.s3')::uuid,now()+interval '11 days');select pg_temp.run_optimizer();
select is((select state from public.optimizer_candidates where sweep_id=current_setting('test.s3')::uuid and profile_id=current_setting('test.p2')::uuid),'skipped','new purchase/revision after approval safely skips later winback/suppression');
select is((select count(*) from public.optimizer_events where kind='suppressed'),1::bigint,'changed protection prevents another suppression');
-- Actual original domain approvals/package/provider/confirmed-send create the own skeleton.
create function pg_temp.sent_template() returns uuid language plpgsql as $$
declare t uuid:='00000000-0000-4000-8000-000000000102';c uuid;j public.job_runs;r uuid;p uuid;row public.campaigns;f public.fixture_deliveries;
begin
 c:=public.save_campaign(t,null,0,jsonb_build_object('title','Original synthetic reusable structure','goal','Educational original note','channel','email_text','planned_at',date_trunc('milliseconds',now()+interval '100 days'),'audience_id','00000000-0000-4000-8000-000000000502'));
 perform public.approve_calendar(t,c,1);perform public.save_copy(t,c,1,'{"subject":"Original own note","preheader":"Fixture","body":"An original educational note for this fictional studio.","cta":"Explore","url":"https://north-studio.example/collection"}');perform public.approve_copy(t,c,2);perform public.enqueue_render(t,c,2,2);
 select * into j from public.claim_job(t);r:=public.finish_render_job(j.id,j.lease_token,'{"synthetic":true,"strips":[]}');perform public.review_render(t,r,3,'approved','whole_design','Owner approved exact synthetic version');select * into row from public.campaigns where id=c;
 p:=public.create_delivery_package(t,c,row.delivery_revision,'{"senderName":"Synthetic North","senderEmail":"studio@north-studio.example","address":"42 Fictional Road, Synthetic Town","unsubscribeUrl":"https://north-studio.example/unsubscribe","privacyUrl":"https://north-studio.example/privacy"}');perform public.enqueue_delivery(t,p,(select revision from public.delivery_packages where id=p));select * into j from public.claim_job(t);
 perform public.fixture_delivery_command(j.id,j.lease_token,'reconcile');perform public.fixture_delivery_command(j.id,j.lease_token,'prepare');perform public.fixture_delivery_command(j.id,j.lease_token,'schedule');perform public.finish_delivery_job(j.id,j.lease_token);select * into f from public.fixture_deliveries where package_id=p;perform public.confirm_fixture_sent(t,f.id,f.scheduled_at);return public.save_own_template(t,f.id);
end $$;
select set_config('test.template',pg_temp.sent_template()::text,true);
select set_config('test.draft',public.draft_from_structure('00000000-0000-4000-8000-000000000102','own_template',current_setting('test.template')::uuid,jsonb_build_object('title','Original own structural draft','goal','Original brand note','channel','email_text','planned_at',now()+interval '100 days','audience_id','00000000-0000-4000-8000-000000000502'))::text,true);
select is((select calendar_state from public.campaigns where id=current_setting('test.draft')::uuid),'proposed','own template starts unapproved calendar');
select is((select copy_state from public.campaigns where id=current_setting('test.draft')::uuid),'draft','template does not reuse executed copy');
select is((select design_state from public.campaigns where id=current_setting('test.draft')::uuid),'unassigned','template never bypasses exact owner design approval');
select is((select lineage->>'structureSource' from public.campaigns where id=current_setting('test.draft')::uuid),'own_template','structural source provenance persists');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select throws_ok($$select public.draft_from_structure('00000000-0000-4000-8000-000000000101','own_template',current_setting('test.template')::uuid,'{}')$$,'42501',null,'foreign own template cannot cross tenant');
select is((select count(*) from public.optimizer_profiles),0::bigint,'foreign owner cannot enumerate profiles');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000003',true);
select is((select count(*) from public.optimizer_profiles),0::bigint,'designer cannot read optimizer profiles');
select throws_ok($$select public.install_optimizer_fixture('00000000-0000-4000-8000-000000000102')$$,'42501',null,'designer cannot operate suppression fixtures');
select * from finish();rollback;
